<?php require '../config.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$s=$pdo->prepare("SELECT * FROM categories WHERE id=?");$s->execute([$id]);$row=$s->fetch();if(!$row)exit('Category not found');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');if($name!==''){try{$s=$pdo->prepare("UPDATE categories SET name=? WHERE id=?");$s->execute([$name,$id]);header('Location: categories.php');exit;}catch(PDOException $e){$error='Could not update category; check duplicate name.';}}}?><!doctype html><html><head><meta charset="utf-8"><title>Edit category</title><link rel="stylesheet" href="../assets/style.css"></head><body><main><h1>Edit Category</h1><p class="error"><?=h($error)?></p><form method="post"><label>Name<input name="name" value="<?=h($row['name'])?>" required></label><button>Save</button></form><a href="categories.php">Back</a></main></body></html>